/* Minimal styles: shell fallbacks mirror real content geometry for stable PPR/streaming. */
main {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1.5rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  margin: 0 0 1.25rem;
}

.card {
  padding: 1rem;
  border: 1px solid #e5e5e5;
  border-radius: 8px;
}

.grid {
  display: grid;
}

.grid-cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.gap-4 {
  gap: 1rem;
}

.chart,
.invoices {
  margin-top: 1.5rem;
}

.chart h2,
.invoices h2 {
  font-size: 1.125rem;
  margin: 0 0 0.75rem;
}

.chart ul,
.invoices ul {
  margin: 0;
  padding-left: 1.25rem;
}

.loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  padding: 2rem;
}

.spinner {
  width: 2rem;
  height: 2rem;
  border: 2px solid #e5e5e5;
  border-top-color: #171717;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.dashboard-shell .skeleton-block {
  min-height: 5.5rem;
  background: linear-gradient(90deg, #f4f4f5 25%, #e4e4e7 50%, #f4f4f5 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s ease-in-out infinite;
}

.skeleton-heading {
  height: 1.125rem;
  width: 8rem;
  margin-bottom: 0.75rem;
  border-radius: 4px;
  background: linear-gradient(90deg, #f4f4f5 25%, #e4e4e7 50%, #f4f4f5 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s ease-in-out infinite;
}

.skeleton-list {
  list-style: none;
  padding-left: 0;
}

.skeleton-line {
  height: 0.875rem;
  margin-bottom: 0.5rem;
  border-radius: 4px;
  max-width: 100%;
  background: linear-gradient(90deg, #f4f4f5 25%, #e4e4e7 50%, #f4f4f5 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s ease-in-out infinite;
}

.skeleton-line.short {
  max-width: 66%;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

